--- index.html
+++ index.html
@@ -32,6 +32,34 @@
 <div class="mobile" id="stick"><div class="stick"></div><div class="nub" id="nub"></div></div><button class="attackbtn mobile" id="touchAttack">⚔</button>
 <div class="modalback" id="modal"><div class="modal"><button class="close" id="closeModal">×</button><div id="modalContent"></div></div></div>
