+const host=document.querySelector('#game'), scene=new THREE.Scene(); scene.background=new THREE.Color('#a9c5b8'); scene.fog=new THREE.FogExp2('#9aafa0',.016);
+const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,180); camera.position.set(0,8,14);
+const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;host.appendChild(renderer.domElement);
+scene.add(new THREE.HemisphereLight(0xc9e7d9,0x293329,2.1));const sun=new THREE.DirectionalLight(0xffdfad,3.2);sun.position.set(-14,24,12);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-35;sun.shadow.camera.right=35;sun.shadow.camera.top=35;sun.shadow.camera.bottom=-35;scene.add(sun);
+const mat=(color,rough=.85,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
+const grass=mat('#536b48'), pathmat=mat('#827458'), stone=mat('#68746a'), gold=mat('#cbaa63',.4,.48), dark=mat('#28372f'), bark=mat('#514333'), leaf=mat('#345b45'), leaf2=mat('#54754b'), glowmat=new THREE.MeshBasicMaterial({color:'#7cecc1'});
+const ground=new THREE.Mesh(new THREE.PlaneGeometry(130,130),grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.09;ground.receiveShadow=true;scene.add(ground);
+// soft mossy ground patches
+for(let i=0;i<100;i++){const x=(Math.random()-.5)*95,z=(Math.random()-.5)*90;const m=new THREE.Mesh(new THREE.CircleGeometry(.4+Math.random()*1.5,9),mat(Math.random()>.5?'#607652':'#455e43'));m.rotation.x=-Math.PI/2;m.position.set(x,-.07,z);m.scale.y=.5;scene.add(m)}
+// winding pale trail
+const trail=new THREE.Mesh(new THREE.PlaneGeometry(7,48),pathmat);trail.rotation.x=-Math.PI/2;trail.position.set(0,-.045,-13);scene.add(trail);
+function addTree(x,z,s=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(s);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.18,.36,3.4,7),bark);trunk.position.y=1.7;trunk.castShadow=true;g.add(trunk);for(let n=0;n<3;n++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(1.35-n*.18,1),n===1?leaf2:leaf);crown.position.set((Math.random()-.5)*.6,3.3+n*.72,(Math.random()-.5)*.4);crown.scale.set(1.15,.85,1);crown.castShadow=true;g.add(crown)}scene.add(g)}
+for(let i=0;i<88;i++){let x,z;do{x=(Math.random()-.5)*65;z=(Math.random()-.5)*58}while(Math.abs(x)<4&&z<4&&z>-30);addTree(x,z,.65+Math.random()*.85)}
+// scattered stones, flowers and lanterns
+for(let i=0;i<70;i++){const x=(Math.random()-.5)*56,z=(Math.random()-.5)*52;if(Math.abs(x)<3&&z<0)continue;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.2+Math.random()*.45,0),stone);rock.position.set(x,.16,z);rock.scale.y=.55;rock.rotation.set(Math.random(),Math.random(),Math.random());rock.castShadow=true;scene.add(rock)}
+function pillar(x,z,h=3){const p=new THREE.Mesh(new THREE.CylinderGeometry(.32,.44,h,8),stone);p.position.set(x,h/2,z);p.castShadow=true;scene.add(p);const cap=new THREE.Mesh(new THREE.CylinderGeometry(.5,.5,.18,8),gold);cap.position.set(x,h+.04,z);scene.add(cap)}
+// ancient ring in the north
+for(let i=0;i<10;i++){let a=i*Math.PI/5,x=Math.sin(a)*5,z=-19+Math.cos(a)*5;pillar(x,z,2.5+(i%3)*.45)}
+const ring=new THREE.Mesh(new THREE.TorusGeometry(2.6,.12,8,48),gold);ring.rotation.x=Math.PI/2;ring.position.set(0,.15,-19);scene.add(ring);
+const portal=new THREE.Mesh(new THREE.TorusGeometry(1.7,.13,10,40),new THREE.MeshStandardMaterial({color:'#72efc2',emissive:'#1fc794',emissiveIntensity:2,metalness:.5}));portal.position.set(0,2.1,-19);scene.add(portal);const portalCore=new THREE.Mesh(new THREE.CircleGeometry(1.58,32),new THREE.MeshBasicMaterial({color:'#34b98d',transparent:true,opacity:.27,side:THREE.DoubleSide}));portalCore.position.set(0,2.1,-19);scene.add(portalCore);
+function humanoid(){const g=new THREE.Group();const robe=new THREE.Mesh(new THREE.CylinderGeometry(.32,.55,1.2,8),mat('#773f76',.65,.18));robe.position.y=.9;robe.castShadow=true;g.add(robe);const torso=new THREE.Mesh(new THREE.SphereGeometry(.34,12,10),mat('#d7b873',.48,.3));torso.position.y=1.48;torso.scale.set(.9,1.1,.65);torso.castShadow=true;g.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.25,14,12),mat('#e4bb8e'));head.position.y=1.98;head.castShadow=true;g.add(head);for(let s of [-1,1]){const ear=new THREE.Mesh(new THREE.ConeGeometry(.075,.38,5),mat('#d6ae81'));ear.position.set(s*.23,2.12,-.02);ear.rotation.z=s*.62;g.add(ear);const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.1,.5,4,7),mat('#d8b27b'));arm.position.set(s*.44,1.38,0);arm.rotation.z=s*-.25;arm.castShadow=true;g.add(arm);const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.12,.42,4,7),dark);leg.position.set(s*.19,.35,0);g.add(leg)}
+const staff=new THREE.Mesh(new THREE.CylinderGeometry(.035,.06,2.2,7),bark);staff.position.set(.66,1.15,.12);staff.rotation.z=-.1;g.add(staff);const orb=new THREE.Mesh(new THREE.IcosahedronGeometry(.19,1),new THREE.MeshStandardMaterial({color:'#96f5e1',emissive:'#24c5a5',emissiveIntensity:2}));orb.position.set(.65,2.3,.12);g.add(orb);g.userData.orb=orb;return g}
+const player=humanoid();player.position.set(0,0,5);scene.add(player);
+function wolf(x,z){const g=new THREE.Group();g.position.set(x,0,z);const fur=mat('#504b46'),headmat=mat('#65574a'),eye=new THREE.MeshBasicMaterial({color:'#fa563e'});const body=new THREE.Mesh(new THREE.SphereGeometry(.57,12,9),fur);body.position.y=.72;body.scale.set(1.35,.75,.78);body.castShadow=true;g.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.34,12,9),headmat);head.position.set(0,1.05,-.55);head.castShadow=true;g.add(head);const snout=new THREE.Mesh(new THREE.ConeGeometry(.2,.48,8),fur);snout.position.set(0,.94,-.88);snout.rotation.x=-Math.PI/2;g.add(snout);for(let s of [-1,1]){const ear=new THREE.Mesh(new THREE.ConeGeometry(.12,.36,5),fur);ear.position.set(s*.21,1.36,-.53);ear.rotation.z=s*.25;g.add(ear);const e=new THREE.Mesh(new THREE.SphereGeometry(.055),eye);e.position.set(s*.23,1.11,-.79);g.add(e);for(let q of [-1,1]){const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.09,.42,3,6),fur);leg.position.set(s*.32,.3,q*.34);leg.castShadow=true;g.add(leg)}}g.userData={type:'wolf',hp:360,max:360,alive:true,aggro:false,attack:0,name:'Сумеречный волк'};scene.add(g);enemies.push(g);return g}
+const enemies=[];wolf(-4,0);wolf(5,-3);wolf(-7,-8);wolf(7,6);wolf(0,-11);
+// friendly quest keeper
+function npc(){const g=new THREE.Group();const robe=new THREE.Mesh(new THREE.ConeGeometry(.48,1.5,7),mat('#345c51'));robe.position.y=.8;g.add(robe);const h=new THREE.Mesh(new THREE.SphereGeometry(.23,12,10),mat('#d6b590'));h.position.y=1.7;g.add(h);const halo=new THREE.Mesh(new THREE.TorusGeometry(.36,.035,6,24),gold);halo.position.y=2.1;g.add(halo);g.position.set(-2,0,-15);scene.add(g);return g}const guide=npc();
+function makeBoss(){const g=new THREE.Group();g.position.set(0,0,-19);const body=new THREE.Mesh(new THREE.IcosahedronGeometry(1.45,1),mat('#263e38',.45,.3));body.position.y=1.5;body.scale.set(1.2,1.4,.9);body.castShadow=true;g.add(body);const head=new THREE.Mesh(new THREE.IcosahedronGeometry(.67,1),mat('#48614c'));head.position.set(0,2.7,-.3);g.add(head);for(let s of [-1,1]){const horn=new THREE.Mesh(new THREE.ConeGeometry(.2,1.1,7),mat('#b29a60',.4,.3));horn.position.set(s*.48,3.35,-.2);horn.rotation.z=s*.45;g.add(horn);const eye=new THREE.Mesh(new THREE.SphereGeometry(.11),new THREE.MeshBasicMaterial({color:'#ff392d'}));eye.position.set(s*.32,2.77,-.88);g.add(eye);const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.24,.9,5,8),mat('#385241'));arm.position.set(s*1.35,1.7,-.1);arm.rotation.z=s*.4;arm.castShadow=true;g.add(arm);for(let j=0;j<3;j++){const spike=new THREE.Mesh(new THREE.ConeGeometry(.22,.7,6),mat('#84935b'));spike.position.set(s*(.55+j*.25),2.3+j*.26,.48);spike.rotation.z=s*.45;g.add(spike)}}g.userData={type:'boss',hp:7000,max:7000,alive:false,name:'Ксар’Вол · Пожиратель корней',attack:0,phase:0};scene.add(g);return g}const boss=makeBoss();boss.visible=false;
+
 </body></html>

