 const msg=(text,kind='sys')=>{const el=document.createElement('div');el.className='msg';el.innerHTML=`<span class="${kind}">[${kind==='combat'?'Бой':'Система'}]</span> ${text}`;document.querySelector('#messages').appendChild(el);while(document.querySelector('#messages').children.length>5)document.querySelector('#messages').firstChild.remove()};
