 function ui(){document.querySelector('#hpText').textContent=`${Math.ceil(health)} / 1000`;document.querySelector('#hpFill').style.width=`${health/10}%`;document.querySelector('#mpText').textContent=`${Math.ceil(mana)} / 420`;document.querySelector('#mpFill').style.width=`${mana/4.2}%`;document.querySelector('#xpText').textContent=`${xp.toLocaleString('ru-RU')} / 3 200`;document.querySelector('#xpFill').style.width=`${Math.min(100,xp/32)}%`;document.querySelector('#goldCount').textContent=goldCount.toLocaleString('ru-RU');document.querySelector('#shardCount').textContent=shards;document.querySelector('#questCount').textContent=`${Math.min(kills,3)} / 3`;if(target){document.querySelector('#target').classList.add('show');document.querySelector('#targetName').textContent=target.userData.name;document.querySelector('#targetLevel').textContent=target===boss?'РЕЙДОВЫЙ БОСС':'Уровень 10';document.querySelector('#targetFill').style.width=`${Math.max(0,target.userData.hp/target.userData.max*100)}%`}else document.querySelector('#target').classList.remove('show');document.querySelector('#bossFill').style.width=`${Math.max(0,boss.userData.hp/boss.userData.max*100)}%`;document.querySelector('#bossPct').textContent=`${Math.ceil(boss.userData.hp/boss.userData.max*100)}%`}
 function modal(title,body){document.querySelector('#modalContent').innerHTML=`<div class="eyebrow">ЭХО ИЗУМРУДНОГО КРУГА</div><h2>${title}</h2>${body}`;document.querySelector('#modal').classList.add('show')}

